import { Component } from '@angular/core';

/**
 * Represents main footer.
 */
@Component({
  selector: 'app-footer',
  templateUrl: './footer.component.html',
  styleUrls: ['./footer.component.css']
})
export class FooterComponent {

}
<footer>
  <div>
    Copyright &#169; 2020-2023, Michał (psysiu) Wójcik
  </div>
  <div>
    All character's portraits were created using
    <a href="http://dmheroes.com">DMHeroes</a> developed by
    <a href="https://twitter.com/ChristianOesch">Christian Oesch</a>.
  </div>
</footer>
